questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-11
Challenge task: reverse rounding by identifying the full whole-number interval that produces a given rounded result.
Original STACK question. No source wording or mathematical content is copied. */
/* Choose the rounding place.
1 = nearest ten 2 = nearest hundred 3 = nearest thousand */
place_choice: rand_with_prohib(1,3,[]);
place_value: if place_choice=1 then 10 elseif place_choice=2 then 100 else 1000;
place_name: if place_choice=1 then "ten" elseif place_choice=2 then "hundred" else "thousand";
/* Choose a positive target multiple. */
target_index: rand_with_prohib( 120, 850, [] );
rounded_value: target_index * place_value;
/* Under school half-up rounding:
smallest included whole number: R - p/2
largest included whole number: R + p/2 - 1
The exact upper halfway point belongs to the next rounded value. */
lower_answer: rounded_value - place_value/2;
upper_answer: rounded_value + place_value/2 - 1;
/* Primary misconception: assume the rounded result corresponds to only one original value. */
wrong_unique_lower: rounded_value;
wrong_unique_upper: rounded_value;
/* Secondary misconception: include the upper halfway boundary even though that value rounds upward to the next multiple. */
wrong_upper_inclusive: rounded_value + place_value/2;
